using MiniStore.Domain.Entities;
using MiniStore.Domain.Interfaces;
namespace MiniStore.Application.Services;
public class BranchService(IBranchRepository repository, IAccountRepository accounts) { public Task<List<Branch>> GetAllAsync()=>repository.GetAllAsync(); public async Task CreateAsync(string code,string name) { if((await repository.GetAllAsync()).Any(x=>x.Code.Equals(code.Trim(),StringComparison.OrdinalIgnoreCase))) throw new InvalidOperationException("Branch code already exists."); await repository.AddAsync(new Branch(code,name)); await repository.SaveChangesAsync(); } public async Task ConfigureSalesAccountAsync(int branchId,int accountId) { var branch=await repository.GetByIdAsync(branchId)??throw new InvalidOperationException("Branch not found."); var account=await accounts.GetByIdAsync(accountId)??throw new InvalidOperationException("Sales account not found."); if(account.ParentAccountId is null) throw new InvalidOperationException("Branch sales account must be a subaccount."); branch.AssignSalesRevenueAccount(accountId); await repository.SaveChangesAsync(); } }
